@Component("routing-entity-projector")
public class RoutingEntityProjector implements EntityProjector<Routing>{
		
	// core constructor
	public RoutingEntityProjector(ProjectorRegistry registry,
										RoutingRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Routing> getEntityClass() {
		return Routing.class;
	}

    /*
	 * Insert a Routing
	 * 
     * @param	entity Routing
     */
    public Routing create( Routing entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Routing
	 * 
     * @param	entity Routing
     */
    public Routing update( Routing entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Routing
	 * 
     * @param	id		UUID
     */
    public Routing delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Routing entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Item
     * 
     * @param	parentId	UUID
     * @param	assignment 	Item 
     * @return	Routing
     */
    public Routing assignItem( UUID parentId, Item assignment ) {
	    LOGGER.info("assigning Item as " + assignment.toString() );

	    Routing parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Item.class, assignment.getItemId());

	    // ------------------------------------------
		// assign the Item to the parent entity
		// ------------------------------------------ 
	    parentEntity.setItem( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Item
	 * 
	 * @param	parentId		UUID
	 * @return	Routing
	 */
	public Routing unAssignItem( UUID parentId ) {
		Routing parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Item on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Item on the parent entithy
		// ------------------------------------------     
	    parentEntity.setItem(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the Operations
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Routing
     */
    public Routing addToOperations( UUID parentId, Operation addTo ) {
	    LOGGER.info("handling AssignOperationsToRoutingEvent - " );
	    
	    Routing parentEntity = repository.findById(parentId).get();
	    Operation child = registry.project( Operation.class, addTo.getOperationId());
	    
	    parentEntity.getOperations().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Operations
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Routing
     */
	public Routing removeFromOperations( UUID parentId, Operation removeFrom ) {
	    LOGGER.info("handling RemoveOperationsFromRoutingEvent " );
	
	    Routing parentEntity = repository.findById(parentId).get();
	    Operation child = registry.project( Operation.class, removeFrom.getOperationId());
	    
	    parentEntity.getOperations().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Routing via an FindRoutingQuery
     * @return 	query	FindRoutingQuery
     */
    @SuppressWarnings("unused")
    public Routing find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Routing - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Routings
     *
     * @param	query	FindAllRoutingQuery 
     * @return 	List<Routing> 
     */
    @SuppressWarnings("unused")
    public List<Routing> findAll( FindAllRoutingQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Routing - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final RoutingRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(RoutingEntityProjector.class.getName());

}
